import json
import os
import re
import sys
from typing import Optional

import requests

from .version import __version__

AHDEV_DIR = os.path.expanduser("~/.ahdev")
UPDATE_CACHE_FILE = os.path.join(AHDEV_DIR, "update_check.json")
UPDATE_CHECK_URL = "http://10.168.66.226:3141/root/autohome/auto-plus-plus"
UPDATE_INDEX_URL = "http://10.168.66.226:3141/root/autohome/simple/"
UPDATE_VERSION_PATTERNS = [
    re.compile(r"Latest version on stage is:\s*(?:<a[^>]*>)?([0-9]+(?:\.[0-9]+)*)(?:</a>)?"),
    re.compile(r"auto_plus_plus-([0-9]+(?:\.[0-9]+)*)\.tar\.gz"),
    re.compile(r"auto_plus_plus-([0-9]+(?:\.[0-9]+)*)-(?:py3-none-any|cp\d+-abi3-[\w.]+)\.whl"),
]


def parse_latest_version(raw_text: str) -> Optional[str]:
    versions = []
    for pattern in UPDATE_VERSION_PATTERNS:
        versions.extend(pattern.findall(raw_text or ""))
    if not versions:
        return None
    return max(versions, key=normalize_version)


def normalize_version(version: str) -> tuple[int, ...]:
    return tuple(int(part) for part in version.split("."))


def is_newer_version(current_version: str, latest_version: str) -> bool:
    current_parts = list(normalize_version(current_version))
    latest_parts = list(normalize_version(latest_version))
    max_len = max(len(current_parts), len(latest_parts))
    current_parts.extend([0] * (max_len - len(current_parts)))
    latest_parts.extend([0] * (max_len - len(latest_parts)))
    return tuple(latest_parts) > tuple(current_parts)


def load_update_cache() -> dict:
    if not os.path.exists(UPDATE_CACHE_FILE):
        return {}
    try:
        with open(UPDATE_CACHE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}


def save_update_cache(cache: dict):
    try:
        os.makedirs(AHDEV_DIR, exist_ok=True)
        with open(UPDATE_CACHE_FILE, "w", encoding="utf-8") as f:
            json.dump(cache, f, ensure_ascii=False, indent=2)
    except OSError:
        pass


def fetch_latest_version(timeout: int = 5) -> Optional[str]:
    response = requests.get(UPDATE_CHECK_URL, timeout=timeout)
    response.raise_for_status()
    return parse_latest_version(response.text)


def get_current_version() -> str:
    return __version__


def _in_virtualenv() -> bool:
    return sys.prefix != getattr(sys, "base_prefix", sys.prefix)


def _is_externally_managed() -> bool:
    """PEP 668：标准库目录存在 EXTERNALLY-MANAGED 标记时需 --break-system-packages
    （Homebrew / Debian 系统 Python）。venv 内不会有该标记。"""
    try:
        import sysconfig

        stdlib = sysconfig.get_path("stdlib")
        return bool(stdlib) and os.path.exists(os.path.join(stdlib, "EXTERNALLY-MANAGED"))
    except Exception:
        return False


def _resolve_auto_python() -> str:
    """返回 auto++ 所在环境的 Python 解释器。

    sys.executable 即当前运行 auto++ 的解释器（= 装了 ahclaude_plugin 的
    那个环境），是首选。仅当它为空（极少数嵌入/冻结场景）时，才从
    auto++ 控制台脚本的 shebang 反解，保证升级仍打到 auto++ 自己的环境，
    而不是 PATH 上某个无关 python。
    """
    exe = sys.executable
    if exe:
        return exe

    # Windows 控制台脚本是 .exe（无 shebang 可解），直接兜底
    if sys.platform == "win32":
        return "python"

    # 非 Windows：从 auto++ 脚本 shebang 反解出同环境解释器
    try:
        import shutil

        auto = shutil.which("auto++")
        if auto:
            with open(auto, "r", encoding="utf-8", errors="ignore") as f:
                first = f.readline().strip()
            if first.startswith("#!"):
                shebang = first[2:].strip()
                # 形如 "#!/path/to/python" 或 "#!/usr/bin/env python3"
                parts = shebang.split()
                cand = parts[1] if parts and parts[0].endswith("env") and len(parts) > 1 else parts[0]
                if cand and os.path.exists(cand):
                    return cand
    except OSError:
        pass

    return "python3"


def _build_upgrade_command() -> str:
    # 对齐 README：清华镜像拉依赖（内网/被墙下 pypi.org 不可达会导致升级失败），
    # 私有源拉 auto-plus-plus 本体，两个源都需 --trusted-host。
    index_args = (
        " -i https://pypi.tuna.tsinghua.edu.cn/simple"
        " --extra-index-url http://10.168.66.226:3141/root/autohome/"
        " --trusted-host 10.168.66.226"
        " --trusted-host pypi.tuna.tsinghua.edu.cn"
    )
    # auto++ 所在环境的解释器，避免 python/python3 歧义和装错环境；
    # 路径含空格（Windows "Program Files"）需加引号。
    py = _resolve_auto_python()
    if " " in py:
        py = f'"{py}"'

    flags = ""
    if not _in_virtualenv():
        # 非 venv：--user 装到用户目录，Mac/Windows 都免 admin、与 README 安装路径一致
        flags = " --user"
        # PEP 668 外部托管（Homebrew/Debian 系统 Python）才需放开
        if _is_externally_managed():
            flags += " --break-system-packages"

    return f"{py} -m pip install{flags} -U auto-plus-plus{index_args}"


def _build_update_message(current_version: str, latest_version: str) -> str:
    return (
        f"[提示] 检测到新版本：当前 {current_version}，最新 {latest_version}\n"
        f"建议先升级后继续使用。\n"
        f"升级命令：{_build_upgrade_command()}"
    )


def maybe_notify_update() -> Optional[str]:
    current_version = get_current_version()
    cache = load_update_cache()

    try:
        latest_version = fetch_latest_version()
    except (requests.RequestException, ValueError):
        return None

    if latest_version:
        if cache.get("latest_version") == latest_version:
            return None
        cache["latest_version"] = latest_version
        save_update_cache(cache)
        if is_newer_version(current_version, latest_version):
            return _build_update_message(current_version, latest_version)

    return None
